def combine(payload, left, right):
    records = []
    for pos, obj in left:
        records.append((pos, obj))
    for pos, obj in right:
        records.append((pos, obj))

    ambiguous = set(payload.get("ambiguous_names", []) or [])

    n = len(records)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

