from datetime import datetime


def _alpha_lower(value):
    if value is None:
        return ""
    return re.sub(r"[^a-z0-9]", "", str(value).lower())


def _digits(value):
    if value is None:
        return ""
    return re.sub(r"[^0-9]", "", str(value))


def _iso_date(value):
    if value is None:
        return ""
    return str(value)


def compute(payload):
