    if len(a) == len(b):
        d = sum(1 for x, y in zip(a, b) if x != y)
        return d <= 1
    # insertion/deletion
    if len(a) < len(b):
        a, b = b, a
    # a is longer by exactly 1
    i = j = 0
    skipped = False
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            i += 1
            j += 1
        else:
            if skipped:
                return False
            skipped = True
            i += 1
    return True


def _name_key(first, last):
